_T_CASE = 38.0
# ⚠️ Mesuré, pas choisi : chaque valeur de chaque plage imprimée à 600 dpi
#    dans sa case, avec le gras du contour, pixels de contact comptés
#    contre les traits de sa grille :
#       36 pt -> 0 contact      38 pt -> 0 contact   ← INSTALLÉ
#       39 pt -> 313 pixels     40 pt -> 1 534 pixels
#    ⭐ Ici chaque numéro a sa propre case fermée : c'est le cadre qui
#      commande, et la règle de lecture du MOOREA ne s'applique pas —
#      les traits séparent déjà les nombres à l'œil.
_T_SERIE = 5.0


def _poser_decor(c, x0, y0):
    """Grave la planche UNE FOIS par document, puis la tamponne.
    ⚠️ La marque est posée SUR LE CANEVAS, jamais dans un dictionnaire
    indexé par id() : Python réutilise les id() libérés."""
    nom = "KEA_DECOR"
    if not getattr(c, "_kea_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                else:
                    p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                              v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                              v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._kea_forme_faite = True
    c.saveState()
    c.translate(x0, y0)
    c.doForm(nom)
    c.restoreState()


def _gen_carte(rng):
    """9 numéros : 3 distincts par colonne, chacun dans sa plage, NON triés
    (fidèle à son modèle : l'ordre vertical est libre)."""
    return [rng.sample(range(pmin, pmax + 1), 3) for pmin, pmax in PLAGES]


# ⚠️ Deux cartons identiques dans la même rame : ce jeu ne peut fabriquer
#    que 165 x 165 x 165 = 4 492 125 cartons différents si l'ordre compte
#    (11 numéros par plage, 3 tirés, l'ordre libre : 990 par colonne, donc
#    990^3 = 970 299 000). Une rame de 500 feuilles en contient 8 000 :
#    le calcul donne 1 risque sur 30. On garde donc en mémoire, pendant
#    tout le document, les cartons déjà sortis.
def _tirer(rng, deja):
    for _ in range(200):
        g = _gen_carte(rng)
        cle = tuple(tuple(c) for c in g)
        if cle not in deja:
            deja.add(cle)
            return g
    return g


def _dessiner_feuille(c, x0, y0, cartes, series, couleur_hex, titre_jeu="",
                      telephone="", style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    col = colors.HexColor(couleur_hex)
    c.setFillColor(col)
    _poser_decor(c, x0, y0)

    def MX(v):
        return x0 + v / 1000.0 * FEUILLE_W

    def MY(v):
        return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (bord, bandeau, cols, rows) in enumerate(GRILLES):
        grille = cartes[gi]
        for ci in range(3):
            cx = MX((cols[ci] + cols[ci + 1]) / 2.0)
            for ri in range(3):
                n = grille[ci][ri]
                cy = MY((rows[ri] + rows[ri + 1]) / 2.0) - _T_CASE * 0.34
                if _sec:
                    _sec.chiffre_micro(c, n, cx, cy, _T_CASE, gris_ch, police_ch,
                                       epaisseur=_GRAS_TRAIT)
                else:
                    c.setFillColor(gris_ch)
                    c.setFont(police_ch, _T_CASE)
                    c.drawCentredString(cx, cy, str(n))
        # le numéro de série, dans le blanc à gauche du bandeau K E A
        c.setFillColor(GRIS)
        c.setFont(POLICE, _T_SERIE)
        c.drawString(MX(bord[0]) + 1.0 * mm, MY(bandeau[1]) + 1.1 * mm,
                     "N° %06d" % series[gi])
        if telephone:
            c.drawRightString(MX(bord[1]) - 1.0 * mm, MY(bandeau[1]) + 1.1 * mm,
                              telephone[:14])
        if _sec:
            try:
                _sec.cadre_micro(c, MX(bord[0]), MY(rows[3]),
                                 MX(bord[1]) - MX(bord[0]),
                                 MY(bandeau[0]) - MY(rows[3]),
                                 series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=16, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", page_start=1):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=landscape(A4), pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    rng = random.Random(964000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()

    for _ in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.6 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.6 * mm, "%03d" % no_page)

        cartes = [_tirer(rng, _deja) for _ in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        coul = (couleur_perso if (couleur and couleur_perso)
                else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur else "#000000")
        _dessiner_feuille(c, MARGE_X, MARGE_Y, cartes, series, coul,
                          titre_jeu, telephone, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf


